import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import type { ComposerFocus, RegisteredComposerFocus } from '../types/composerFocusTypes'
import { attachedContextLogic } from './attachedContextLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface composerFocusLogicValues {
    focus: RegisteredComposerFocus | null
    providers: Record<string, ComposerFocus>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface composerFocusLogicActions {
    dismissContext: (
        key: string,
        dismissGroup?: string | undefined
    ) => {
        dismissGroup: string | undefined
        key: string
    } // attachedContextLogic
    closeFocus: (providerId: string) => {
        providerId: string
    }
    deregisterFocus: (providerId: string) => {
        providerId: string
    }
    registerFocus: (
        providerId: string,
        focus: ComposerFocus
    ) => {
        focus: ComposerFocus
        providerId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface composerFocusLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        focus: (providers: Record<string, ComposerFocus>) => RegisteredComposerFocus | null
    }
}

export type composerFocusLogicType = MakeLogicType<
    composerFocusLogicValues,
    composerFocusLogicActions,
    Record<string, any>,
    composerFocusLogicMeta
>

/**
 * Global registry of the one thing the composer is focused on, e.g. the notebook cell a user asked
 * about. The composer renders it above the textbox in place of the welcome state, and the side panel
 * keeps a compact copy above the thread once a run starts.
 *
 * Unlike `attachedContextLogic`, only one focus renders, so the last registration wins: the most
 * recent click is what the user is asking about.
 */
export const composerFocusLogic = kea<composerFocusLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'composerFocusLogic']),

    connect(() => ({
        actions: [attachedContextLogic, ['dismissContext']],
    })),

    actions({
        /** Idempotent upsert. Re-registering moves the provider to the front, so it becomes the focus. */
        registerFocus: (providerId: string, focus: ComposerFocus) => ({ providerId, focus }),
        deregisterFocus: (providerId: string) => ({ providerId }),
        /** The user closed the card: drop the focus and dismiss the context group it stands for. */
        closeFocus: (providerId: string) => ({ providerId }),
    }),

    reducers({
        providers: [
            {} as Record<string, ComposerFocus>,
            {
                registerFocus: (state, { providerId, focus }) => {
                    const { [providerId]: _previous, ...rest } = state
                    return { ...rest, [providerId]: focus }
                },
                deregisterFocus: (state, { providerId }) => {
                    if (!(providerId in state)) {
                        return state
                    }
                    const { [providerId]: _dropped, ...rest } = state
                    return rest
                },
            },
        ],
    }),

    selectors({
        focus: [
            (s) => [s.providers],
            (providers: Record<string, ComposerFocus>): RegisteredComposerFocus | null => {
                const entries = Object.entries(providers)
                if (entries.length === 0) {
                    return null
                }
                const [providerId, focus] = entries[entries.length - 1]
                return { ...focus, providerId }
            },
        ],
    }),

    listeners(({ actions, values }) => ({
        registerFocus: () => {
            // Two live hosts means one of them forgot to deregister, and its card can come back later.
            if (process.env.NODE_ENV === 'development' && Object.keys(values.providers).length > 1) {
                console.warn(
                    '[composerFocusLogic] More than one composer focus is registered; the last one wins.',
                    Object.keys(values.providers)
                )
            }
        },
        closeFocus: ({ providerId }) => {
            const focus = values.providers[providerId]
            if (!focus) {
                return
            }
            actions.deregisterFocus(providerId)
            if (focus.dismissGroup) {
                actions.dismissContext(`composer_focus:${focus.id}`, focus.dismissGroup)
            }
        },
    })),
])
